/* file : FilesMapper.xml, id : getFileList */
SELECT *
  FROM TB_FILES
 WHERE DEL_YN = 'N'
   AND REF_TP = #{refTp}
   AND REF_SEQ  = #{refSeq}

/* file : FilesMapper.xml, id : getDtFileList */
SELECT *
  FROM TB_MODEL_FILES
 WHERE DEL_YN = 'N'
   AND REF_TP = #{refTp}
   AND MODEL_SEQ  = #{refSeq}

/* file : FilesMapper.xml, id : getFile */
SELECT *
  FROM TB_FILES
 WHERE DEL_YN = 'N'
   AND FILE_SEQ = #{file_seq}

/* file : FilesMapper.xml, id : getDtFile */
SELECT *
  FROM TB_MODEL_FILES
 WHERE DEL_YN = 'N'
   AND FILE_SEQ = #{file_seq}

/* file : FilesMapper.xml, id : getDtAugmentFile */
SELECT *
  FROM TB_AUGMENT_MODEL_FILES
 WHERE DEL_YN = 'N'
   AND FILE_SEQ = #{file_seq}

mapper.insert:
/* file : FilesMapper.xml, id : insertFile */
INSERT
  INTO TB_FILES (
              FILE_SEQ
            , REF_TP
            , REF_SEQ
            , FILE_TP
            , FILE_NM
            , FILE_TITLE
            , FILE_PATH
            , FILE_EXTN
            , FILE_SZ
            , FILE_CONTS_TP
            , REG_USER_SEQ
            , REG_IP
            )
       VALUES (
             nextval('seq_tb_files_file_seq')
            , #{refTp}
            , #{refSeq}
            , #{fileTp}
            , #{fileNm}
            , #{fileTitle}
            , #{filePath}
            , #{fileExtn}
            , #{fileSz}
            , #{fileContsTp}
            , #{loginUserSeq}
            , #{loginUserIp}
            )

/* file : FilesMapper.xml, id : insertDtFile */
INSERT
  INTO TB_MODEL_FILES (
              FILE_SEQ
            , MODEL_SEQ
            , REF_TP
            , FILE_NM
            , FILE_PATH
            , FILE_EXTN
            , FILE_SZ
            , FILE_CONTS_TP
            , REG_USER_SEQ
            , REG_IP
            )
       VALUES (
             #{fileSeq}
            , #{refSeq}
            , #{refTp}
            , #{fileNm}
            , #{filePath}
            , #{fileExtn}
            , #{fileSz}
            , #{fileContsTp}
            , #{loginUserSeq}
            , #{loginUserIp}
            )

		SELECT LAST_INSERT_ID()

mapper.update:
/* file : FilesMapper.xml, id : updateFile */
UPDATE TB_FILES
   SET FILE_PATH         = #{filePath}
     , FILE_CONTS_TP = #{fileContsTp}
     , STRG_FILE_NM	 = #{strgFileNm}
	 , THUMB_S    = #{thumbS}
	 , THUMB_M    = #{thumbM}
	 , THUMB_L    = #{thumbL}
 WHERE FILE_SEQ          = #{fileSeq}

/* file : FilesMapper.xml, id : updateDtFile */
UPDATE TB_MODEL_FILES
   SET FILE_PATH         = #{filePath}
     , FILE_CONTS_TP = #{fileContsTp}
     , FILE_NM	 = #{fileNm}
     , STRG_FILE_NM	 = #{strgFileNm}
 WHERE FILE_SEQ          = #{fileSeq}

/* file : FilesMapper.xml, id : updateDtFile */
UPDATE TB_AUGMENT_MODEL_FILES
   SET FILE_PATH         = #{filePath}
     , FILE_CONTS_TP = #{fileContsTp}
     , FILE_NM	 = #{fileNm}
     , STRG_FILE_NM	 = #{strgFileNm}
 WHERE FILE_SEQ          = #{fileSeq}

/* file : FilesMapper.xml, id : deleteFile */
UPDATE TB_FILES
   SET DEL_YN     = 'Y'
     , DEL_USER_SEQ = #{loginUserSeq}
     , DEL_DT     = CURRENT_TIMESTAMP
     , DEL_IP       = #{loginUserIp}
 WHERE FILE_SEQ     = #{fileSeq}

/* file : FilesMapper.xml, id : deleteFile */
UPDATE TB_FILES
   SET DEL_YN     = 'Y'
     , DEL_USER_SEQ = #{loginUserSeq}
     , DEL_DT     = CURRENT_TIMESTAMP
     , DEL_IP       = #{loginUserIp}
 WHERE REF_TP     = #{refTp}
   AND REF_SEQ      = #{refSeq}

/* file : FilesMapper.xml, id : updateFileTitle */
UPDATE TB_FILES
   SET FILE_TITLE   = #{fileTitle}
     , MDFCN_USER_SEQ = #{loginUserSeq}
     , MDFCN_DT     = CURRENT_TIMESTAMP
     , MOD_IP       = #{loginUserIp}
 WHERE FILE_SEQ     = #{fileSeq}

/* file : FilesMapper.xml, id : updateThumbFile */
UPDATE TB_FILES
   SET THUMB_S    = #{thumbS}
	 , THUMB_M    = #{thumbM}
	 , THUMB_L    = #{thumbL}
 WHERE FILE_SEQ          = #{fileSeq}

